import{z as o,x as s,o as B,c as d,q as A,j as r,D as l,d as a,s as n,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"生产案例与失败模式","description":"","frontmatter":{"title":"生产案例与失败模式","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/continual-production-cases.md","filePath":"llm/continual-production-cases.md","lastUpdated":1791063341000}'),p={name:"llm/continual-production-cases.md"};function m(c,E,D,f,C,h){const t=s("Mermaid");return B(),d("div",null,[E[2]||(E[2]=A('<h1 id="生产案例与失败模式" tabindex="-1">生产案例与失败模式 <a class="header-anchor" href="#生产案例与失败模式" aria-label="Permalink to &quot;生产案例与失败模式&quot;">​</a></h1><div class="epigraph"><p>持续学习在生产里坏掉的方式大同小异：多数事故是流程缺陷穿着数学外衣。</p><footer>—— 据 De Lange 等 2021（持续学习综述）与公开工程事后报告整理</footer></div><p><a href="/llm/continual-eval-protocol">上一课</a>把记分制度立了起来；本课看真实环里实际会断的位置。案例按「现象-根因-机制」组织，机制都有前文出处；本课不引入新方法，只把失败归到正确的机制上，指出每类的早期信号。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>失败清单值得单列，因为持续学习环的失效模式与静态模型不同：静态模型的退化是外因，坏起来多半是依赖故障；持续学习环的退化常是内因——环自己生产训练数据、自己消费自己的输出，坏得缓、因果绕。用静态事故直觉排查，会把根因找错层。</p><h3 id="七类高频失败" tabindex="-1">七类高频失败 <a class="header-anchor" href="#七类高频失败" aria-label="Permalink to &quot;七类高频失败&quot;">​</a></h3><p>一、静默过期：监控只布在性能层，输入分布早移了，用户投诉时已过期数月。早期信号是<a href="/llm/continual-drift-detection">输入层监控</a>的缓慢趋势线，不是报警。二、自食回路：模型输出经用户点选回流成训练数据，几轮后语气谄媚、长度膨胀——环内偏置逐圈放大，<a href="/llm/reward-hacking-llm">奖励黑客</a>与<a href="/llm/self-preference-bias">自我偏好</a>的复合。三、缓冲区泄漏：回放池原样存提示，一次访问控制事故变成一次数据事故，本该在入库前由<a href="/llm/continual-feedback-privacy">隐私闸门</a>拦下。四、版本错位：基座升级后旧适配器未重验，行为漂移被误判为「模型不稳定」；配对要像<a href="/llm/adapter-hot-swap">适配器热更新</a>的回滚键一样显式。五、更新风暴：为追指标放宽发布门带宽，一天数更，回归混在进步里上线——台账缺位时，没人能指出从哪一更开始坏的。六、题库泄漏：滚动基准的题被拿去训练，成绩虚涨掩盖真实过期，是<a href="/llm/eval-contamination">评测去污染</a>的再现。七、假遗忘：聊天模板或系统提示改动，探针全线下降，像极了遗忘——先比对提示 diff，再动权重。</p><p><span class="marginnote">第二类有个可量化前兆：训练数据里「模型自产文本」的占比。占比过半且缺人工锚定时，自食回路基本闭合——先降占比或加人工锚，再谈调参。</span></p><p><span class="marginnote">自食回路可以想象成回音室：模型说的话被用户点选，又被当成「好答案」喂回训练，几圈之后房间里只剩它自己的回声。可怕之处在于每一步单看都合理，没有任何一次更新算「出错」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>归因顺序值得写成固定流程：第一步排除第七类（提示 diff，最便宜）；第二步查第五、六类（台账与污染扫描，纯属文书与检索）；第三步用<a href="/llm/continual-drift-detection">冻结影子模型</a>分离「世界变了」与「改坏了」；最后才进权重级诊断。多数团队把顺序反过来——先怀疑模型、重训一版——结果在二、六、七类失败上把环越搅越糟。</p><p><span class="marginnote">初学者容易把「探针全线下降」当成遗忘，立刻去调权重。实际上聊天模板改一个引号、系统提示换一句措辞，分数就能全线跳水——所以归因第一步永远是比对提示 diff，这是全场最便宜的一步检查。</span></p>',12)),(B(),r(i,null,{default:l(()=>[n(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYM%5B%22%E6%8C%87%E6%A0%87%E5%BC%82%E5%B8%B8%E6%88%96%E6%8A%95%E8%AF%89%22%5D%20--%3E%20Q1%7B%22%E6%8F%90%E7%A4%BA%2F%E6%A8%A1%E6%9D%BF%E6%9C%80%E8%BF%91%E6%94%B9%E8%BF%87%E5%90%97%3F%22%7D%0A%20%20Q1%20--%3E%7C%E6%98%AF%7C%20PSEUDO%5B%22%E5%81%87%E9%81%97%E5%BF%98%EF%BC%9A%E5%85%88%E5%9B%9E%E6%BB%9A%E6%8F%90%E7%A4%BA%22%5D%0A%20%20Q1%20--%3E%7C%E5%90%A6%7C%20Q2%7B%22%E5%8F%B0%E8%B4%A6%E8%83%BD%E5%AE%9A%E4%BD%8D%E5%88%B0%E5%8D%95%E6%AC%A1%E6%9B%B4%E6%96%B0%E5%90%97%3F%22%7D%0A%20%20Q2%20--%3E%7C%E4%B8%8D%E8%83%BD%7C%20STORM%5B%22%E5%85%88%E4%BF%AE%E5%8F%B0%E8%B4%A6%E4%B8%8E%E5%8F%91%E5%B8%83%E9%97%A8%22%5D%0A%20%20Q2%20--%3E%7C%E8%83%BD%7C%20Q3%7B%22%E5%86%BB%E7%BB%93%E5%BD%B1%E5%AD%90%E5%90%8C%E9%99%8D%E5%90%97%3F%22%7D%0A%20%20Q3%20--%3E%7C%E5%90%A6%7C%20REG%5B%22%E5%9B%9E%E5%BD%92%EF%BC%9A%E5%9B%9E%E6%BB%9A%E8%AF%A5%E6%AC%A1%E6%9B%B4%E6%96%B0%22%5D%0A%20%20Q3%20--%3E%7C%E6%98%AF%7C%20DRIFT%5B%22%E4%B8%96%E7%95%8C%E5%8F%98%E4%BA%86%EF%BC%9A%E8%B5%B0%E6%BC%82%E7%A7%BB%E5%A4%84%E7%BD%AE%E9%A2%84%E6%A1%88%22%5D%0A"})]),fallback:l(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("这些失败共享一个深层结构：每个部件单独看都正常，坏的是部件间的"),e("strong",null,"时序耦合"),a("。检测器有延迟，发布门有带宽，缓冲区有保留期，适配器有兼容期——各自的「正常延迟」连起来，可以长到任何单一监控都看不见问题。事后报告里常见的「每个环节都按规范做了」正因此：规范按部件写，事故按链条发生。对策不是加监控，而是缩短链条：发布门与回滚以小时计，台账查询以分钟计，任何「等下个周期再看」都在给耦合加长。")],-1)),E[5]||(E[5]=e("p",null,"把每个部件的「正常延迟」串成一条链，问题出在哪一段就清楚了：",-1)),(B(),r(i,null,{default:l(()=>[n(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E8%BE%93%E5%85%A5%E5%BC%80%E5%A7%8B%E6%BC%82%E7%A7%BB%22%5D%20--%3E%20B%5B%22%E6%A3%80%E6%B5%8B%E5%99%A8%3A%E8%B6%8B%E5%8A%BF%E7%BA%BF%E8%A6%81%E6%95%B0%E5%A4%A9%E6%89%8D%E7%A1%AE%E8%AE%A4%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%8F%91%E5%B8%83%E9%97%A8%3A%E4%B8%80%E5%A4%A9%E5%8F%AA%E6%94%BE%E8%A1%8C%E5%87%A0%E6%AC%A1%E6%9B%B4%E6%96%B0%22%5D%0A%20%20C%20--%3E%20D%5B%22%E7%BC%93%E5%86%B2%E5%8C%BA%3A%E4%BF%9D%E7%95%99%E6%9C%9F%E4%B8%80%E5%88%B0%E6%97%A7%E6%95%B0%E6%8D%AE%E6%B8%85%E9%99%A4%22%5D%0A%20%20D%20--%3E%20E%5B%22%E9%80%82%E9%85%8D%E5%99%A8%3A%E8%B7%A8%E5%9F%BA%E5%BA%A7%E7%89%88%E6%9C%AC%E8%A6%81%E9%87%8D%E6%96%B0%E9%AA%8C%E8%AF%81%22%5D%0A%20%20E%20--%3E%20F%5B%22%E6%9A%B4%E9%9C%B2%E6%97%B6%E5%B7%B2%E8%AF%B4%E4%B8%8D%E6%B8%85%E5%9D%8F%E5%9C%A8%E5%93%AA%E4%B8%80%E7%8E%AF%22%5D%0A"})]),fallback:l(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=A('<p><span class="marginnote">为什么缩短链条这么重要：如果回滚要等一个发布周期、台账要人工翻记录，那么从「坏更新上线」到「能回滚」的窗口里，坏数据会持续回流进缓冲区、污染下一轮训练——一次事故就滚成了连环事故。</span></p><p>另一层是激励：环把「模型在变」常态化后，团队对变化的敏感度钝化——每周都更新，就没人再为单次更新辩护或质疑。第七类高发正因「提示改动」小到不走发布流程；补丁是把提示纳入与权重同级的版本管理。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>清单的用法有边界：类别是复合与匿名化的归纳，不要逐字对号入座；它的价值是<strong>检查表</strong>——新环上线前过一遍七类，问每类的闸门在哪。也防幸存者偏差：搜得到的事后报告是少数，没有失败案例不等于环健康，可能只是没人看台账。第七类还提示一个反直觉结论：持续学习系统最便宜的可靠性投资，常不在学习算法上，而在「别把不是学习的东西当成学习」的流程纪律上。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>持续学习环的退化多是内因：环自产训练数据、自消费输出，失效因果绕、速度缓。</li><li>七类高频失败各有出处与早期信号：静默过期、自食回路、缓冲泄漏、版本错位、更新风暴、题库泄漏、假遗忘。</li><li>归因按成本排序：先提示 diff，再台账与污染扫描，再影子分离，最后才动权重诊断。</li><li>失败的深层结构是部件时序耦合：缩短发布门、回滚、台账的时延比增加监控有效。</li><li>提示与权重同级版本管理；「小改动不走流程」是最常见的事故入口。</li><li>出处：De Lange 等 2021 的持续学习综述与公开工程事后报告的复合归纳。</li></ul>',6))])}const _=o(p,[["render",m]]);export{F as __pageData,_ as default};
